"""Generate Supabase-compatible PostgreSQL DDL without connecting to a database."""
from pathlib import Path
from sqlalchemy.dialects import postgresql
from sqlalchemy.schema import CreateIndex, CreateTable
from models import Base


def generate_sql():
    dialect = postgresql.dialect()
    statements = [
        "-- Generated by python backend/generate_schema.py; do not edit by hand.",
        "-- Bootstrap for an empty database, not an upgrade or a data import.",
        "-- FastAPI uses a server-only PostgreSQL connection; Supabase Auth is not wired yet.",
        "BEGIN;",
        "SET LOCAL search_path TO public;",
    ]
    for table in Base.metadata.sorted_tables:
        statements.append(str(CreateTable(table, if_not_exists=True).compile(dialect=dialect)).strip() + ";")
        for index in sorted(table.indexes, key=lambda item: item.name):
            statements.append(str(CreateIndex(index, if_not_exists=True).compile(dialect=dialect)) + ";")
        # These tables contain custom-auth data. No browser access until Auth/RLS policies are implemented.
        statements.append(f'ALTER TABLE public."{table.name}" ENABLE ROW LEVEL SECURITY;')
        statements.append(f'REVOKE ALL ON TABLE public."{table.name}" FROM anon, authenticated;')
    statements.append("COMMIT;")
    return "\n\n".join(statements) + "\n"


if __name__ == "__main__":
    target = Path(__file__).resolve().parent / "sql" / "supabase_schema.sql"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(generate_sql(), encoding="utf-8")
    print(f"Generated {target}")
